sql:
SELECT SUM(revenue_gbp) AS total_revenue_gbp_2025
FROM sales
WHERE month >= '2025-01' AND month <= '2025-12';

SELECT SUM(revenue_gbp) AS total_revenue_gbp
FROM sales
WHERE month >= '2025-01' AND month <= '2025-12';

SELECT SUM(revenue_gbp) AS total_revenue_gbp_2025
FROM sales
WHERE month >= '2025-01' AND month <= '2025-12';

SELECT SUM(volume_cases) AS total_cases_2023
FROM sales
WHERE month >= '2023-01' AND month <= '2023-12';

SELECT COUNT(DISTINCT product_id) AS promoted_products_2025
FROM promotions
WHERE month >= '2025-01' AND month <= '2025-12';

SELECT ROUND(AVG(pr.discount_pct), 1) AS avg_discount_pct_energy_2025
FROM promotions pr JOIN products p USING (product_id)
WHERE p.category = 'Energy' AND pr.month LIKE '2025-%';

SELECT ROUND(AVG(pr.discount_pct), 1) AS avg_discount_pct_energy_2025
FROM promotions pr JOIN products p USING (product_id)
WHERE p.category = 'Energy' AND pr.month LIKE '2025-%';
